import express from 'express';
import { init, getAuthToken } from '@heyputer/puter.js/src/init.cjs';
import { randomUUID } from 'crypto';

// ─── Configuration ───────────────────────────────────────────
const PORT = parseInt(process.env.PUTER_API_PORT || '8741', 10);
const HOST = process.env.PUTER_API_HOST || '127.0.0.1';
const API_KEY = process.env.PUTER_API_KEY || null;
const DEFAULT_MODEL = process.env.PUTER_API_DEFAULT_MODEL || 'gpt-4o';

// ─── Model Mapping ───────────────────────────────────────────
const MODEL_ALIASES = {
  'gpt-4o': 'gpt-4o',
  'gpt-4o-mini': 'gpt-4o-mini',
  'gpt-4': 'gpt-4o',
  'gpt-4-turbo': 'gpt-4o',
  'gpt-3.5-turbo': 'gpt-4o-mini',
  'gpt-5-nano': 'gpt-5-nano',
  'gpt-5.4-nano': 'gpt-5.4-nano',
  'gpt-5.4': 'gpt-5.4',
  'claude-sonnet-4': 'claude-sonnet-4',
  'claude-sonnet-4-5': 'claude-sonnet-4-5',
  'claude-3-5-sonnet-20241022': 'claude-sonnet-4',
  'claude-3-5-haiku-20241022': 'claude-sonnet-4',
  'gemini-2.5-flash': 'gemini-2.5-flash',
  'gemini-2.5-flash-lite': 'gemini-2.5-flash-lite',
  'gemini-2.5-pro': 'gemini-2.5-pro',
};

function resolveModel(requestedModel) {
  if (!requestedModel) return DEFAULT_MODEL;
  return MODEL_ALIASES[requestedModel] || requestedModel;
}

// Inverse alias map: target -> alias keys
function getAliasKeysForTarget(target) {
  const aliases = [];
  for (const [alias, resolved] of Object.entries(MODEL_ALIASES)) {
    if (resolved === target && alias !== target) aliases.push(alias);
  }
  return aliases;
}

// ─── Puter Init ──────────────────────────────────────────────
let puterReady = false;
let puter = null;
let cachedModels = null;
let cachedModelsTimestamp = 0;
const MODELS_CACHE_TTL = 5 * 60 * 1000; // 5 minutes

async function ensurePuter() {
  if (!puterReady) {
    try {
      // In Node.js environment we need to authenticate
      const authToken = await getAuthToken();
      puter = init(authToken);
      puterReady = true;
    } catch (error) {
      console.error("Failed to initialize Puter:", error);
      throw new Error("Failed to initialize Puter SDK. " + error.message);
    }
  }
}

// ─── Express App ─────────────────────────────────────────────
const app = express();

app.use(express.json({ limit: '50mb' }));

// CORS headers
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', '*');
  res.header('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  if (req.method === 'OPTIONS') return res.sendStatus(204);
  next();
});

// Optional API key authentication
if (API_KEY) {
  app.use((req, res, next) => {
    if (req.path === '/' || req.path === '/health') return next();
    const auth = req.headers.authorization;
    if (!auth || !auth.startsWith('Bearer ') || auth.slice(7) !== API_KEY) {
      return res.status(401).json({
        error: {
          message: 'Invalid API key',
          type: 'invalid_request_error',
          code: 'invalid_api_key',
        },
      });
    }
    next();
  });
}

// Request logging
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    const ts = new Date().toISOString();
    console.log(`[${ts}] ${req.method} ${req.path} ${res.statusCode} ${duration}ms`);
  });
  next();
});

// ─── Routes ──────────────────────────────────────────────────

app.get('/', (req, res) => {
  res.json({
    status: 'ok',
    service: 'puter-api-bridge',
    version: '1.0.0',
    endpoints: {
      chat: '/v1/chat/completions',
      models: '/v1/models',
    },
  });
});

app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

// ─── GET /v1/models ──────────────────────────────────────────
app.get('/v1/models', async (req, res) => {
  try {
    await ensurePuter();

    const now = Date.now();
    if (cachedModels && (now - cachedModelsTimestamp) < MODELS_CACHE_TTL) {
      return res.json(cachedModels);
    }

    let sdkModels = [];
    try {
      const result = await puter.ai.listModels();
      sdkModels = Array.isArray(result) ? result : [];
    } catch {
      sdkModels = [];
    }

    // Build set of canonical model IDs from SDK
    const canonicalIds = new Set();
    const providerMap = {};
    for (const m of sdkModels) {
      const id = typeof m === 'string' ? m : (m.id || m.name);
      if (id) {
        canonicalIds.add(String(id));
        if (m.provider) providerMap[String(id)] = m.provider;
      }
    }

    // If SDK returned nothing, use alias targets as fallback
    if (canonicalIds.size === 0) {
      for (const id of Object.values(MODEL_ALIASES)) {
        canonicalIds.add(id);
      }
    }

    // Include all alias keys that map to known models
    for (const [alias, target] of Object.entries(MODEL_ALIASES)) {
      if (canonicalIds.has(target) && alias !== target) {
        canonicalIds.add(alias);
      }
    }

    const models = Array.from(canonicalIds).map(id => ({
      id,
      object: 'model',
      created: Math.floor(now / 1000),
      owned_by: providerMap[id] || 'puter',
    }));

    const response = { object: 'list', data: models };

    cachedModels = response;
    cachedModelsTimestamp = now;

    res.json(response);
  } catch (err) {
    console.error('[models] Error:', err.message);
    res.status(500).json({
      error: {
        message: err.message,
        type: 'server_error',
      },
    });
  }
});

// ─── POST /v1/chat/completions ───────────────────────────────
app.post('/v1/chat/completions', async (req, res) => {
  try {
    await ensurePuter();

    const {
      model: requestedModel,
      messages,
      stream = false,
      temperature,
      max_tokens,
      tools,
      top_p,
      frequency_penalty,
      presence_penalty,
      n,
      stop,
    } = req.body;

    if (!messages || !Array.isArray(messages) || messages.length === 0) {
      return res.status(400).json({
        error: {
          message: 'messages is required and must be a non-empty array',
          type: 'invalid_request_error',
          code: 'invalid_messages',
        },
      });
    }

    const model = resolveModel(requestedModel);
    const requestId = `chatcmpl-${randomUUID().replace(/-/g, '').slice(0, 29)}`;
    const created = Math.floor(Date.now() / 1000);

    const puterOptions = { model };
    if (temperature !== undefined) puterOptions.temperature = temperature;
    if (max_tokens !== undefined) puterOptions.max_tokens = max_tokens;

    if (tools && Array.isArray(tools) && tools.length > 0) {
      puterOptions.tools = tools;
    }

    const puterMessages = messages.map((msg) => {
      const mapped = { role: msg.role, content: msg.content };
      if (msg.tool_calls) mapped.tool_calls = msg.tool_calls;
      if (msg.tool_call_id) mapped.tool_call_id = msg.tool_call_id;
      if (msg.name) mapped.name = msg.name;
      return mapped;
    });

    if (stream) {
      res.setHeader('Content-Type', 'text/event-stream');
      res.setHeader('Cache-Control', 'no-cache');
      res.setHeader('Connection', 'keep-alive');
      res.setHeader('X-Accel-Buffering', 'no');
      res.flushHeaders();

      puterOptions.stream = true;

      try {
        const puterStream = await puter.ai.chat(puterMessages, puterOptions);

        const initialChunk = {
          id: requestId,
          object: 'chat.completion.chunk',
          created,
          model,
          choices: [
            {
              index: 0,
              delta: { role: 'assistant', content: '' },
              finish_reason: null,
            },
          ],
        };
        res.write(`data: ${JSON.stringify(initialChunk)}\n\n`);

        let toolCalls = [];

        for await (const part of puterStream) {
          if (part?.text) {
            const chunk = {
              id: requestId,
              object: 'chat.completion.chunk',
              created,
              model,
              choices: [
                {
                  index: 0,
                  delta: { content: part.text },
                  finish_reason: null,
                },
              ],
            };
            res.write(`data: ${JSON.stringify(chunk)}\n\n`);
          }

          if (part?.type === 'tool_use') {
            const toolCallChunk = {
              id: requestId,
              object: 'chat.completion.chunk',
              created,
              model,
              choices: [
                {
                  index: 0,
                  delta: {
                    tool_calls: [
                      {
                        index: toolCalls.length,
                        id: part.id || `call_${randomUUID().replace(/-/g, '').slice(0, 24)}`,
                        type: 'function',
                        function: {
                          name: part.name,
                          arguments: JSON.stringify(part.input || {}),
                        },
                      },
                    ],
                  },
                  finish_reason: null,
                },
              ],
            };
            toolCalls.push(part);
            res.write(`data: ${JSON.stringify(toolCallChunk)}\n\n`);
          }
        }

        const finalChunk = {
          id: requestId,
          object: 'chat.completion.chunk',
          created,
          model,
          choices: [
            {
              index: 0,
              delta: {},
              finish_reason: toolCalls.length > 0 ? 'tool_calls' : 'stop',
            },
          ],
        };
        res.write(`data: ${JSON.stringify(finalChunk)}\n\n`);
        res.write('data: [DONE]\n\n');
        res.end();
      } catch (streamErr) {
        console.error('[stream] Error:', streamErr.message);
        const errorChunk = {
          id: requestId,
          object: 'chat.completion.chunk',
          created,
          model,
          choices: [
            {
              index: 0,
              delta: { content: `\n\n[Error: ${streamErr.message}]` },
              finish_reason: 'stop',
            },
          ],
        };
        res.write(`data: ${JSON.stringify(errorChunk)}\n\n`);
        res.write('data: [DONE]\n\n');
        res.end();
      }
    } else {
      const puterResponse = await puter.ai.chat(puterMessages, puterOptions);

      let content = '';
      let toolCallsResult = null;
      let finishReason = 'stop';

      if (puterResponse?.message) {
        const msg = puterResponse.message;
        if (typeof msg.content === 'string') {
          content = msg.content;
        } else if (Array.isArray(msg.content)) {
          content = msg.content
            .filter((c) => c.type === 'text')
            .map((c) => c.text)
            .join('');
        }

        if (msg.tool_calls && msg.tool_calls.length > 0) {
          finishReason = 'tool_calls';
          toolCallsResult = msg.tool_calls.map((tc) => ({
            id: tc.id || `call_${randomUUID().replace(/-/g, '').slice(0, 24)}`,
            type: 'function',
            function: {
              name: tc.function?.name || tc.name,
              arguments:
                typeof tc.function?.arguments === 'string'
                  ? tc.function.arguments
                  : JSON.stringify(tc.function?.arguments || tc.input || {}),
            },
          }));
        }
      } else if (typeof puterResponse === 'string') {
        content = puterResponse;
      } else if (puterResponse?.toString) {
        content = puterResponse.toString();
      }

      const promptTokens = JSON.stringify(messages).length / 4;
      const completionTokens = content.length / 4;

      const response = {
        id: requestId,
        object: 'chat.completion',
        created,
        model,
        choices: [
          {
            index: 0,
            message: {
              role: 'assistant',
              content: toolCallsResult ? null : content,
              ...(toolCallsResult ? { tool_calls: toolCallsResult } : {}),
            },
            finish_reason: finishReason,
          },
        ],
        usage: {
          prompt_tokens: Math.ceil(promptTokens),
          completion_tokens: Math.ceil(completionTokens),
          total_tokens: Math.ceil(promptTokens + completionTokens),
        },
      };

      res.json(response);
    }
  } catch (err) {
    console.error('[chat] Error:', err.message);
    res.status(500).json({
      error: {
        message: err.message || 'Internal server error',
        type: 'server_error',
        code: 'internal_error',
      },
    });
  }
});

app.use('/v1', (req, res) => {
  res.status(404).json({
    error: {
      message: `Endpoint ${req.method} ${req.path} is not implemented. Available endpoints: POST /v1/chat/completions, GET /v1/models`,
      type: 'invalid_request_error',
      code: 'endpoint_not_found',
    },
  });
});

// ─── Start Server ────────────────────────────────────────────
export async function startServer() {
  const server = app.listen(PORT, HOST, () => {
    console.log(`[${new Date().toISOString()}] Puter API Bridge v1.0.0`);
    console.log(`[${new Date().toISOString()}] Listening on http://${HOST}:${PORT}`);
    console.log(`[${new Date().toISOString()}] Default model: ${DEFAULT_MODEL}`);
    console.log(`[${new Date().toISOString()}] API key required: ${API_KEY ? 'yes' : 'no'}`);
    console.log(`[${new Date().toISOString()}] Endpoints:`);
    console.log(`  POST /v1/chat/completions`);
    console.log(`  GET  /v1/models`);
  });

  const shutdown = (signal) => {
    console.log(`\n[${new Date().toISOString()}] Received ${signal}, shutting down...`);
    server.close(() => {
      console.log(`[${new Date().toISOString()}] Server closed.`);
      process.exit(0);
    });
    setTimeout(() => process.exit(1), 5000);
  };

  process.on('SIGTERM', () => shutdown('SIGTERM'));
  process.on('SIGINT', () => shutdown('SIGINT'));

  return server;
}

if (process.argv[1] && (process.argv[1].endsWith('server.js') || process.argv[1].endsWith('server'))) {
  startServer().catch((err) => {
    console.error('Failed to start server:', err);
    process.exit(1);
  });
}
